import { Text, Container } from "@earendil-works/pi-tui";

export default function summaryExt(pi) {
  pi.on("session_start", (_e, ctx) => {
    if (typeof ctx.ui?.setFooter !== "function") return;
    ctx.ui.setFooter((_tui, theme, footerData) => {
      return {
        render(width) {
          const prov = footerData.getAvailableProviderCount();
          const statuses = footerData.getExtensionStatuses();
          return [
            theme.fg("dim", `K4-FOOTER w=${width} p=${prov} st=${statuses.size}`),
          ];
        },
        invalidate() {},
      };
    });
  });
}
